// Bad: Fixed retry interval locks servers into overload
async function retryRequest(fn, retries = 3) {
  for (let i = 0; i < retries; i++) {
    try { return await fn(); }
    catch (err) {
      await sleep(1000); // Fixed 1-second delay
    }
  }
}

