// Good: Exponential backoff with random full jitter
async function retryWithJitter(fn, retries = 4, baseMs = 200, maxMs = 5000) {
  for (let attempt = 0; attempt < retries; attempt++) {
    try {
      return await fn();
    } catch (err) {
      if (attempt === retries - 1) throw err;
      const backoff = Math.min(maxMs, baseMs * Math.pow(2, attempt));
      const jitter = Math.random() * backoff;
      await sleep(jitter);
    }
  }
}
